import { useEffect, useMemo, useState, type FormEvent } from "react";
import { useLocation } from "wouter";
import { CalendarDays, Users, Scissors, Settings, Wallet, Menu, X, Search, ChevronLeft, ChevronRight, LoaderCircle, Clock, LogOut, Plus, Check, Ban, Circle, MessageCircle, UserRound, Save, Pencil, ToggleLeft, ToggleRight, Eye, Droplets, Palette, Waves } from "lucide-react";
import { toast } from "sonner";
import { useQueryClient } from "@tanstack/react-query";
import { trpc } from "@/lib/trpc";

type Section = "agenda" | "clientes" | "servicos" | "equipe" | "configuracoes" | "caixa";
const paths: Record<string, Section> = { "/app": "agenda", "/app/agenda": "agenda", "/app/clientes": "clientes", "/app/servicos": "servicos", "/app/equipe": "equipe", "/app/configuracoes": "configuracoes" };
const hrefs: Record<Section, string> = { agenda: "/app/agenda", clientes: "/app/clientes", servicos: "/app/servicos", equipe: "/app/equipe", configuracoes: "/app/configuracoes", caixa: "/app/caixa" };
const labels: Record<Section, string> = { agenda: "Agenda", clientes: "Clientes", servicos: "Serviços", equipe: "Equipe", configuracoes: "Configurações", caixa: "Caixa" };
const icons: Record<Section, typeof CalendarDays> = { agenda: CalendarDays, clientes: Users, servicos: Scissors, equipe: UserRound, configuracoes: Settings, caixa: Wallet };
const serviceIcons = ["scissors", "beard", "razor", "hair", "eyebrow", "pigment", "hydration", "relaxation", "star"] as const;
const statusText: Record<string, string> = { scheduled: "Agendado", confirmed: "Confirmado", in_progress: "Em andamento", completed: "Concluído", cancelled: "Cancelado", no_show: "Não compareceu" };
const statusStyle: Record<string, string> = { scheduled: "bg-stone-100 text-stone-600", confirmed: "bg-blue-50 text-blue-700", in_progress: "bg-amber-50 text-amber-700", completed: "bg-emerald-50 text-emerald-700", cancelled: "bg-rose-50 text-rose-700", no_show: "bg-stone-100 text-stone-500" };
const brl = (v: number) => Number(v).toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
const dateKey = (d: Date) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
const dateKeyInZone = (value: Date, timezone: string) => {
  const parts = new Intl.DateTimeFormat("en-CA", { timeZone: timezone, year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(value);
  const part = (type: string) => parts.find(item => item.type === type)?.value ?? "00";
  return `${part("year")}-${part("month")}-${part("day")}`;
};
const inputClass = "mt-1.5 h-10 w-full rounded-md border border-stone-200 bg-white px-3 text-sm outline-none focus:border-amber-700";
const weekDayLabels = ["Domingo", "Segunda", "Terça", "Quarta", "Quinta", "Sexta", "Sábado"];
type WorkingHour = { weekday: number; startTime: string; endTime: string; breakStart: string | null; breakEnd: string | null; isDayOff: boolean };
const defaultWorkingHours = (): WorkingHour[] => weekDayLabels.map((_, weekday) => ({ weekday, startTime: "09:00", endTime: "18:00", breakStart: weekday === 0 ? null : "13:00", breakEnd: weekday === 0 ? null : "14:00", isDayOff: weekday === 0 }));
const birthdayMonthDay = (value: unknown) => value instanceof Date ? `${String(value.getUTCMonth() + 1).padStart(2, "0")}-${String(value.getUTCDate()).padStart(2, "0")}` : typeof value === "string" ? value.slice(5, 10) : "";
const birthdayDateInput = (value: unknown) => value instanceof Date ? value.toISOString().slice(0, 10) : typeof value === "string" ? value.slice(0, 10) : "";

export default function OperationsConsole() {
  const [location, setLocation] = useLocation();
  const [mobileOpen, setMobileOpen] = useState(false);
  const [day, setDay] = useState(() => new Date());
  const [calendarMode, setCalendarMode] = useState<"day" | "week" | "month">("day");
  const [selectedBarberId, setSelectedBarberId] = useState("");
  const [search, setSearch] = useState("");
  const [payingId, setPayingId] = useState<number | null>(null);
  const [paymentMethod, setPaymentMethod] = useState<"cash"|"pix"|"credit"|"debit"|"other">("pix");
  const [machineFee, setMachineFee] = useState("0");
  const [productSelection, setProductSelection] = useState<{ productId: number; quantity: number }[]>([]);
  const [selectedServiceIds, setSelectedServiceIds] = useState<number[]>([]);
  const [productDraftId, setProductDraftId] = useState("");
  const [productDraftQuantity, setProductDraftQuantity] = useState("1");
  const [editingService, setEditingService] = useState<number | null>(null);
  const [showService, setShowService] = useState(false);
  const [serviceForm, setServiceForm] = useState({ name:"", category:"", iconKey:"scissors", price:"", durationMinutes:"30" });
  const [showTeam, setShowTeam] = useState(false);
  const [hoursBarberId, setHoursBarberId] = useState("");
  const [editingCustomerId, setEditingCustomerId] = useState<number | null>(null);
  const [expandedHistoryCustomerId, setExpandedHistoryCustomerId] = useState<number | null>(null);
  const [customerDraft, setCustomerDraft] = useState({ birthday: "", notes: "" });
  const [workingHoursForm, setWorkingHoursForm] = useState<WorkingHour[]>(defaultWorkingHours);
  const [teamForm, setTeamForm] = useState({ name:"", email:"", password:"", role:"barber" as "barber"|"receptionist", serviceIds:[] as number[] });
  const [settingsForm, setSettingsForm] = useState({ name:"", slug:"", logoUrl:"", bannerImageUrl:"", primaryColor:"#9b8054", cancellationNoticeHours:24, plansVisible:false, promotionsEnabled:false, couponsEnabled:false, loyaltyEnabled:false, reviewsEnabled:false, galleryEnabled:false });
  const queryClient = useQueryClient();
  const me = trpc.management.tenant.me.useQuery(undefined, { retry: false });
  const role = me.data?.staff.role;
  const isOwner = role === "owner";
  const isBarber = role === "barber";
  const section = paths[location] ?? (location === "/app/caixa" ? "caixa" : "agenda");
  const nav: Section[] = role === "barber" ? ["agenda"] : role === "receptionist" ? ["agenda", "clientes", "caixa"] : ["agenda", "clientes", "servicos", "equipe", "configuracoes"];
  const dateStart = calendarMode === "month"
    ? new Date(day.getFullYear(), day.getMonth(), 1)
    : calendarMode === "week"
      ? new Date(day.getFullYear(), day.getMonth(), day.getDate() - ((day.getDay() + 6) % 7))
      : new Date(day.getFullYear(), day.getMonth(), day.getDate());
  const dateEnd = calendarMode === "month"
    ? new Date(day.getFullYear(), day.getMonth() + 1, 1)
    : calendarMode === "week"
      ? new Date(dateStart.getFullYear(), dateStart.getMonth(), dateStart.getDate() + 7)
      : new Date(dateStart.getFullYear(), dateStart.getMonth(), dateStart.getDate() + 1);
  const appointments = trpc.management.tenant.appointments.useQuery({ from: dateStart, to: dateEnd, barberId: selectedBarberId ? Number(selectedBarberId) : undefined }, { enabled: !!role && section === "agenda" });
  const agendaTeam = trpc.management.tenant.team.useQuery(undefined, { enabled: !!isOwner && section === "agenda" });
  const waitlist = trpc.management.tenant.waitlist.useQuery(undefined, { enabled: !!isOwner && section === "agenda" });
  const customers = trpc.management.tenant.customers.useQuery({ search }, { enabled: !!role && section === "clientes", retry: false });
  const customerHistory = trpc.management.tenant.customerHistory.useQuery({ customerId: expandedHistoryCustomerId ?? 0 }, { enabled: !!role && section === "clientes" && Boolean(expandedHistoryCustomerId) });
  const services = trpc.management.tenant.services.useQuery(undefined, { enabled: !!role && (section === "servicos" || section === "equipe" || (section === "agenda" && isOwner)) });
  const appointmentServices = trpc.management.tenant.appointmentServices.useQuery({ id: payingId ?? 0 }, { enabled: !!role && payingId !== null });
  const saleProducts = trpc.business.inventory.products.useQuery(undefined, { enabled: !!role && section === "agenda" });
  const team = trpc.management.tenant.team.useQuery(undefined, { enabled: !!role && section === "equipe" });
  const reviewStats = trpc.management.tenant.reviewStats.useQuery(undefined, { enabled: !!isOwner && section === "configuracoes" });
  const workingHours = trpc.management.tenant.workingHours.useQuery({ barberId: Number(hoursBarberId) }, { enabled: !!isOwner && section === "equipe" && Boolean(hoursBarberId) });
  const statusUpdate = trpc.management.tenant.updateAppointmentStatus.useMutation({ onSuccess: async () => { toast.success("Agendamento atualizado."); setPayingId(null); await queryClient.invalidateQueries(); }, onError: e => toast.error(e.message) });
  const createService = trpc.management.tenant.createService.useMutation({ onSuccess: async () => { toast.success("Serviço cadastrado."); setShowService(false); await queryClient.invalidateQueries(); }, onError: e => toast.error(e.message) });
  const updateService = trpc.management.tenant.updateService.useMutation({ onSuccess: async () => { toast.success("Serviço atualizado."); setEditingService(null); await queryClient.invalidateQueries(); }, onError: e => toast.error(e.message) });
  const createMember = trpc.management.tenant.createTeamMember.useMutation({ onSuccess: async () => { toast.success("Acesso criado. A pessoa deverá trocar a senha no primeiro acesso."); setShowTeam(false); setTeamForm({ name:"", email:"", password:"", role:"barber", serviceIds:[] }); await queryClient.invalidateQueries(); }, onError: e => toast.error(e.message) });
  const saveWorkingHours = trpc.management.tenant.saveWorkingHours.useMutation({ onSuccess: async () => { toast.success("Expediente salvo."); await queryClient.invalidateQueries(); }, onError: e => toast.error(e.message) });
  const updateCustomer = trpc.management.tenant.updateCustomer.useMutation({ onSuccess: async () => { toast.success("Cadastro do cliente atualizado."); setEditingCustomerId(null); await queryClient.invalidateQueries(); }, onError: e => toast.error(e.message) });
  const updateWaitlistStatus = trpc.management.tenant.updateWaitlistStatus.useMutation({ onSuccess: async () => { toast.success("Fila atualizada."); await queryClient.invalidateQueries(); }, onError: e => toast.error(e.message) });
  const updateSettings = trpc.management.tenant.updateSettings.useMutation({ onSuccess: async () => { toast.success("Configurações salvas."); await queryClient.invalidateQueries(); }, onError: e => toast.error(e.message) });
  const createBannerUpload = trpc.management.tenant.createBannerUpload.useMutation();
  const logout = trpc.staff.logout.useMutation({ onSuccess: async () => { await queryClient.invalidateQueries(); setLocation("/login"); } });
  useEffect(() => { if (!hoursBarberId && team.data?.barbers[0]) setHoursBarberId(String(team.data.barbers[0].id)); }, [hoursBarberId, team.data]);
  useEffect(() => { if (appointmentServices.data) setSelectedServiceIds([...new Set(appointmentServices.data.flatMap(item => item.serviceId === null ? [] : [item.serviceId]))]); }, [appointmentServices.data, payingId]);
  useEffect(() => { if (workingHours.data?.length === 7) setWorkingHoursForm(workingHours.data.map(row => ({ weekday: row.weekday, startTime: row.startTime.slice(0,5), endTime: row.endTime.slice(0,5), breakStart: row.breakStart?.slice(0,5) ?? null, breakEnd: row.breakEnd?.slice(0,5) ?? null, isDayOff: row.isDayOff }))); }, [workingHours.data]);
  useEffect(() => { if (me.data) setSettingsForm(f => ({ ...f, name:me.data.shop.name, slug:me.data.shop.slug, logoUrl:me.data.shop.logoUrl || "", bannerImageUrl:me.data.shop.bannerImageUrl || "", primaryColor:me.data.shop.primaryColor || "#9b8054", cancellationNoticeHours:me.data.shop.cancellationNoticeHours, plansVisible:me.data.shop.plansVisible, promotionsEnabled:me.data.shop.promotionsEnabled, couponsEnabled:me.data.shop.couponsEnabled, loyaltyEnabled:me.data.shop.loyaltyEnabled, reviewsEnabled:me.data.shop.reviewsEnabled, galleryEnabled:me.data.shop.galleryEnabled })); }, [me.data]);
  const filteredAppointments = useMemo(() => (appointments.data ?? []).filter(a => `${a.customerName} ${a.barberName ?? ""} ${a.bookingRef}`.toLocaleLowerCase("pt-BR").includes(search.toLocaleLowerCase("pt-BR"))), [appointments.data, search]);
  const appointmentGroups = useMemo(() => {
    const groups = new Map<string, typeof filteredAppointments>();
    for (const appointment of filteredAppointments) {
      const key = dateKeyInZone(new Date(appointment.startsAt), me.data?.shop.timezone ?? "America/Sao_Paulo");
      groups.set(key, [...(groups.get(key) ?? []), appointment]);
    }
    return [...groups.entries()].sort(([left], [right]) => left.localeCompare(right));
  }, [filteredAppointments, me.data?.shop.timezone]);
  const shiftCalendar = (offset: number) => setDay(current => {
    if (calendarMode === "day") return new Date(current.getFullYear(), current.getMonth(), current.getDate() + offset);
    if (calendarMode === "week") return new Date(current.getFullYear(), current.getMonth(), current.getDate() + offset * 7);
    const targetMonth = new Date(current.getFullYear(), current.getMonth() + offset, 1);
    const dayOfMonth = Math.min(current.getDate(), new Date(targetMonth.getFullYear(), targetMonth.getMonth() + 1, 0).getDate());
    return new Date(targetMonth.getFullYear(), targetMonth.getMonth(), dayOfMonth);
  });
  const go = (s: Section) => { setLocation(hrefs[s]); setMobileOpen(false); setSearch(""); };
  const askComplete = (id: number) => { setPayingId(id); setPaymentMethod("pix"); setMachineFee("0"); setProductSelection([]); setSelectedServiceIds([]); setProductDraftId(""); setProductDraftQuantity("1"); };
  const completeWithPayment = () => { if (payingId) statusUpdate.mutate({ id:payingId, status:"completed", paymentMethod, machineFee:Number(machineFee || 0), products:productSelection, serviceIds:selectedServiceIds }); };
  const uploadBannerImage = async (file: File) => {
    const allowedTypes = ["image/jpeg", "image/png", "image/webp"];
    if (!allowedTypes.includes(file.type)) { toast.error("Envie uma imagem JPG, PNG ou WebP."); return; }
    if (file.size > 5 * 1024 * 1024) { toast.error("A imagem deve ter até 5 MB."); return; }
    try {
      const ticket = await createBannerUpload.mutateAsync({ fileSize: file.size, contentType: file.type as "image/jpeg" | "image/png" | "image/webp" });
      const uploaded = await fetch(ticket.uploadUrl, { method: "PUT", headers: { "Content-Type": ticket.contentType }, body: file });
      if (!uploaded.ok) throw new Error("Não foi possível enviar a imagem. Tente novamente.");
      await updateSettings.mutateAsync({ bannerImageUrl: ticket.bannerImageUrl });
      setSettingsForm(current => ({ ...current, bannerImageUrl: ticket.bannerImageUrl }));
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Falha ao atualizar o banner.");
    }
  };
  const submitService = (e: FormEvent) => { e.preventDefault(); const base = { name:serviceForm.name.trim(), category:serviceForm.category.trim(), iconKey:serviceForm.iconKey, price:Number(serviceForm.price), durationMinutes:Number(serviceForm.durationMinutes) }; if(editingService) updateService.mutate({ id:editingService, ...base }); else createService.mutate({ ...base, isActive:true }); };
  const beginEdit = (s: any) => { setEditingService(s.id); setServiceForm({ name:s.name, category:s.category, iconKey:serviceIcons.includes(s.iconKey) ? s.iconKey : "scissors", price:String(s.price), durationMinutes:String(s.durationMinutes) }); setShowService(true); };
  const submitTeam = (e: FormEvent) => { e.preventDefault(); createMember.mutate({ ...teamForm, name:teamForm.name.trim(), email:teamForm.email.trim(), serviceIds:teamForm.role === "barber" ? teamForm.serviceIds : [] }); };
  if (me.isPending) return <div className="grid min-h-screen place-items-center bg-[#f6f5f2] text-stone-500"><div className="flex items-center gap-2 text-sm"><LoaderCircle className="animate-spin" size={18}/>Carregando sua sessão…</div></div>;
  if (me.isError || !me.data) return <div className="grid min-h-screen place-items-center bg-[#f6f5f2] p-6"><div className="max-w-md rounded-xl border border-stone-200 bg-white p-7 text-center"><h1 className="font-serif text-2xl">Não foi possível abrir o painel</h1><p className="mt-2 text-sm text-stone-500">{me.error?.message || "Sua sessão não está disponível. Entre novamente para continuar."}</p><button onClick={() => setLocation("/login")} className="mt-5 rounded-md bg-stone-900 px-4 py-2 text-sm text-white">Ir para entrar</button></div></div>;
  if (me.data.staff.mustChangePassword) return <div className="grid min-h-screen place-items-center bg-[#f6f5f2] p-6 text-center"><div><h1 className="font-serif text-2xl">Troca de senha necessária</h1><p className="mt-2 text-sm text-stone-500">Altere sua senha antes de usar o painel.</p><button onClick={() => setLocation("/alterar-senha")} className="mt-4 rounded-md bg-stone-900 px-4 py-2 text-sm text-white">Alterar senha</button></div></div>;
  if (role === "super_admin") return <div className="grid min-h-screen place-items-center text-sm text-stone-500">Este painel é exclusivo da equipe da barbearia.</div>;
  if (!nav.includes(section)) return <div className="grid min-h-screen place-items-center bg-[#f6f5f2] p-5 text-center"><div><h1 className="font-serif text-2xl">Seção indisponível para seu perfil</h1><button onClick={() => go("agenda")} className="mt-4 rounded-md bg-stone-900 px-4 py-2 text-sm text-white">Abrir agenda</button></div></div>;

  const sidebar = <><div className="flex h-[76px] items-center gap-3 px-6"><div className="grid h-10 w-10 place-items-center rounded-full border border-amber-700/40 text-amber-200"><Scissors size={18}/></div><div><p className="font-serif text-lg text-white">{me.data.shop.name}</p><p className="text-[10px] uppercase tracking-[.18em] text-stone-400">Painel da barbearia</p></div></div><nav className="mt-6 space-y-1 px-3">{nav.map(s => { const Icon=icons[s]; return <button key={s} onClick={() => go(s)} className={`flex w-full items-center gap-3 rounded-md px-3 py-3 text-left text-sm ${section===s ? "bg-white/10 text-amber-100" : "text-stone-300 hover:bg-white/5"}`}><Icon size={17}/>{labels[s]}</button>; })}</nav>{isOwner && <><p className="mt-6 px-5 pb-2 text-[10px] font-semibold uppercase tracking-[.16em] text-stone-500">Gestão</p><nav className="space-y-1 px-3">{[["Caixa", "/app/caixa"], ["Financeiro", "/app/financeiro"], ["Planos", "/app/planos"], ["Estoque", "/app/estoque"], ["Comissões", "/app/comissoes"], ["Relatórios", "/app/relatorios"]].map(([label, path]) => <button key={path} onClick={() => setLocation(path)} className="flex w-full items-center rounded-md px-3 py-2.5 text-left text-sm text-stone-300 hover:bg-white/5">{label}</button>)}</nav></>}{isBarber && <nav className="mt-6 space-y-1 px-3"><button onClick={() => setLocation("/app/comissoes")} className="flex w-full items-center rounded-md px-3 py-2.5 text-left text-sm text-stone-300 hover:bg-white/5">Minhas comissões</button></nav>}<div className="mt-auto px-4 pb-5"><button onClick={() => logout.mutate()} className="flex w-full items-center gap-2 border-t border-white/10 pt-4 text-sm text-stone-300"><LogOut size={16}/>Sair da conta</button></div></>;
  return <div className="min-h-screen bg-[#f6f5f2] text-stone-800"><aside className="fixed inset-y-0 left-0 z-30 hidden w-[250px] flex-col bg-[#20201d] lg:flex">{sidebar}</aside>{mobileOpen && <div className="fixed inset-0 z-40 bg-black/40 lg:hidden" onClick={() => setMobileOpen(false)}><aside className="flex h-full w-[min(300px,85vw)] flex-col bg-[#20201d]" onClick={e=>e.stopPropagation()}>{sidebar}</aside></div>}<main className="lg:ml-[250px]"><header className="sticky top-0 z-20 flex h-[66px] items-center justify-between border-b border-stone-200 bg-white/95 px-4 sm:px-7"><div className="flex items-center gap-3"><button className="lg:hidden" aria-label="Abrir menu" onClick={() => setMobileOpen(!mobileOpen)}>{mobileOpen?<X size={20}/>:<Menu size={20}/>}</button><span className="text-xs text-stone-500">{me.data.shop.name} <span className="mx-1">/</span>{labels[section]}</span></div><span className="text-xs text-stone-500">{me.data.staff.name}</span></header><div className="mx-auto max-w-[1240px] px-4 pb-12 pt-7 sm:px-7 lg:px-10">
    {section === "agenda" && <>
      <div className="flex flex-wrap items-end justify-between gap-4">
        <div>
          <p className="text-[10px] font-semibold uppercase tracking-[.2em] text-amber-800">Atendimentos</p>
          <h1 className="mt-1 font-serif text-3xl">{calendarMode === "day" ? "Agenda do dia" : calendarMode === "week" ? "Agenda da semana" : "Agenda do mês"}</h1>
          <p className="mt-1 text-sm text-stone-500">{calendarMode === "day"
            ? day.toLocaleDateString("pt-BR", { timeZone: me.data.shop.timezone, weekday: "long", day: "numeric", month: "long", year: "numeric" })
            : `${dateStart.toLocaleDateString("pt-BR", { timeZone: me.data.shop.timezone, day: "numeric", month: "short" })} – ${new Date(dateEnd.getTime() - 1).toLocaleDateString("pt-BR", { timeZone: me.data.shop.timezone, day: "numeric", month: "short", year: "numeric" })}`}</p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <div className="flex rounded-md border border-stone-200 bg-white p-1">{(["day", "week", "month"] as const).map(mode => <button key={mode} onClick={() => setCalendarMode(mode)} className={`rounded px-3 py-1.5 text-xs ${calendarMode === mode ? "bg-stone-900 text-white" : "text-stone-600 hover:bg-stone-50"}`}>{mode === "day" ? "Dia" : mode === "week" ? "Semana" : "Mês"}</button>)}</div>
          <button onClick={() => shiftCalendar(-1)} aria-label="Período anterior" className="grid h-9 w-9 place-items-center rounded border border-stone-200 bg-white"><ChevronLeft size={17}/></button>
          <button onClick={() => setDay(new Date())} className="h-9 rounded border border-stone-200 bg-white px-3 text-xs">Hoje</button>
          <button onClick={() => shiftCalendar(1)} aria-label="Próximo período" className="grid h-9 w-9 place-items-center rounded border border-stone-200 bg-white"><ChevronRight size={17}/></button>
        </div>
      </div>
      <div className="mt-5 flex flex-wrap items-center gap-3">
        <div className="relative min-w-[240px] max-w-md flex-1"><Search size={16} className="absolute left-3 top-3 text-stone-400"/><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Buscar cliente, referência ou responsável" className="h-10 w-full rounded-md border border-stone-200 bg-white pl-9 pr-3 text-sm outline-none focus:border-amber-700"/></div>
        {isOwner && <select aria-label="Filtrar por barbeiro" value={selectedBarberId} onChange={e => setSelectedBarberId(e.target.value)} className="h-10 min-w-[190px] rounded-md border border-stone-200 bg-white px-3 text-sm"><option value="">Todos os barbeiros</option>{(agendaTeam.data?.barbers ?? []).map(barber => <option key={barber.id} value={barber.id}>{barber.displayName}</option>)}</select>}
      </div>
      {appointments.isLoading || (isOwner && agendaTeam.isLoading) ? <Loading/> : appointments.isError ? <ErrorBox message={appointments.error.message}/> : filteredAppointments.length === 0 ? <Empty text={search || selectedBarberId ? "Nenhum atendimento corresponde aos filtros." : "Nenhum agendamento neste período."}/> : <div className="mt-5 space-y-6">{appointmentGroups.map(([date, rows]) => <section key={date}>{calendarMode !== "day" && <h2 className="mb-3 border-b border-stone-200 pb-2 text-sm font-semibold capitalize">{new Date(`${date}T12:00:00`).toLocaleDateString("pt-BR", { weekday: "long", day: "numeric", month: "long", timeZone: me.data.shop.timezone })}</h2>}<div className="space-y-3">{rows.map(a => <article key={a.id} className="rounded-lg border border-stone-200 bg-white p-4 sm:p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div className="flex gap-4"><div className="min-w-[54px] pt-0.5 text-sm font-semibold tabular-nums">{new Date(a.startsAt).toLocaleTimeString("pt-BR", { timeZone: me.data.shop.timezone, hour: "2-digit", minute: "2-digit" })}</div><div><p className="font-medium">{a.customerName}</p><p className="mt-1 text-xs text-stone-500">{a.barberName ? `Responsável: ${a.barberName}` : "Responsável não definido"} · ref. {a.bookingRef}</p></div></div><span className={`rounded-full px-2.5 py-1 text-[11px] ${statusStyle[a.status] ?? statusStyle.scheduled}`}>{statusText[a.status] ?? a.status}</span></div>{!isBarber && a.total !== null && <p className="ml-[70px] mt-2 text-xs text-stone-500">{brl(Number(a.total))}</p>}<div className="mt-4 flex flex-wrap gap-2 sm:ml-[70px]">{a.status === "scheduled" && <button onClick={() => statusUpdate.mutate({ id: a.id, status: "confirmed" })} className="inline-flex items-center gap-1 rounded border border-blue-200 px-3 py-2 text-xs text-blue-800"><Check size={14}/>Confirmar</button>}{a.status === "confirmed" && <button onClick={() => statusUpdate.mutate({ id: a.id, status: "in_progress" })} className="inline-flex items-center gap-1 rounded border border-amber-200 px-3 py-2 text-xs text-amber-800"><Clock size={14}/>Iniciar</button>}{a.status === "in_progress" && <button onClick={() => askComplete(a.id)} className="inline-flex items-center gap-1 rounded bg-stone-900 px-3 py-2 text-xs text-white"><Check size={14}/>Concluir</button>}{["scheduled", "confirmed"].includes(a.status) && <button onClick={() => statusUpdate.mutate({ id: a.id, status: "cancelled" })} className="inline-flex items-center gap-1 rounded border border-rose-200 px-3 py-2 text-xs text-rose-700"><Ban size={14}/>Cancelar</button>}{a.status === "scheduled" && <button onClick={() => statusUpdate.mutate({ id: a.id, status: "no_show" })} className="inline-flex items-center gap-1 rounded border border-stone-200 px-3 py-2 text-xs text-stone-600"><Circle size={14}/>Não compareceu</button>}</div></article>)}</div></section>)}</div>}
      {isOwner && <section className="mt-8 rounded-lg border border-stone-200 bg-white p-5"><div className="flex items-center justify-between gap-3"><div><h2 className="font-serif text-xl">Fila de espera</h2><p className="mt-1 text-xs text-stone-500">Confira pedidos de encaixe e convide manualmente quando surgir uma vaga.</p></div><span className="rounded-full bg-amber-50 px-2.5 py-1 text-xs text-amber-900">{waitlist.data?.length ?? 0}</span></div>{waitlist.isLoading ? <Loading/> : waitlist.isError ? <ErrorBox message={waitlist.error.message}/> : !waitlist.data?.length ? <p className="mt-4 text-sm text-stone-500">Nenhuma pessoa aguardando encaixe.</p> : <div className="mt-4 divide-y divide-stone-100">{waitlist.data.map(entry => { const wanted = (entry.serviceIds as number[]).map(id => services.data?.find(service => service.id === id)?.name).filter(Boolean).join(" · "); return <div key={entry.id} className="flex flex-wrap items-center justify-between gap-3 py-3"><div><p className="text-sm font-medium">{entry.customerName}</p><p className="mt-1 text-xs text-stone-500">{wanted || "Serviços selecionados"}{entry.desiredDate ? ` · data desejada ${String(entry.desiredDate).slice(0,10)}` : ""}{entry.barberId ? ` · barbeiro #${entry.barberId}` : " · qualquer profissional"}</p></div><div className="flex gap-2"><a target="_blank" rel="noreferrer" href={`https://wa.me/${String(entry.whatsapp).replace(/\D/g, "")}?text=${encodeURIComponent(`Olá ${entry.customerName}, surgiu uma possibilidade de encaixe na ${me.data.shop.name}. Quer confirmar um horário?`)}`} className="rounded-md border border-emerald-200 px-3 py-2 text-xs text-emerald-800">Chamar no WhatsApp</a><button disabled={updateWaitlistStatus.isPending} onClick={() => updateWaitlistStatus.mutate({ id: entry.id, status: "contacted" })} className="rounded-md border border-stone-200 px-3 py-2 text-xs text-stone-600">Marcar contatado</button></div></div>; })}</div>}</section>}
    </>}
    {section === "clientes" && <>
      <Title eyebrow="Relacionamento" title="Clientes" desc="Histórico e contatos da clientela desta barbearia."/>
      <div className="relative mt-6 max-w-md"><Search size={16} className="absolute left-3 top-3 text-stone-400"/><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Buscar por nome ou WhatsApp" className="h-10 w-full rounded-md border border-stone-200 bg-white pl-9 pr-3 text-sm outline-none focus:border-amber-700"/></div>
      {customers.isLoading ? <Loading/> : customers.isError ? <ErrorBox message={customers.error.message}/> : <>
        {!search && role === "owner" && !!customers.data?.length && <div className="mt-5 grid gap-4 xl:grid-cols-2">
          <section className="rounded-lg border border-stone-200 bg-white p-4"><h2 className="font-serif text-lg">Aniversariantes deste mês</h2>{customers.data.filter(c => birthdayMonthDay(c.birthday).slice(0, 2) === String(new Date().getMonth() + 1).padStart(2, "0")).length ? <div className="mt-2 divide-y divide-stone-100">{customers.data.filter(c => birthdayMonthDay(c.birthday).slice(0, 2) === String(new Date().getMonth() + 1).padStart(2, "0")).map(c => <div key={c.id} className="flex items-center justify-between gap-2 py-2"><span className="text-xs">{c.name} · {birthdayMonthDay(c.birthday).slice(3, 5)}/{birthdayMonthDay(c.birthday).slice(0, 2)}</span><a target="_blank" rel="noreferrer" href={`https://wa.me/${String(c.whatsapp).replace(/\D/g, "")}?text=${encodeURIComponent(`Feliz aniversário, ${c.name}! A equipe da ${me.data.shop.name} deseja um ótimo dia. Quando quiser, será um prazer te receber.`)}`} className="rounded border border-emerald-200 px-2 py-1 text-[10px] text-emerald-800">Chamar</a></div>)}</div> : <p className="mt-2 text-xs text-stone-500">Nenhum aniversário cadastrado para este mês.</p>}</section>
          <section className="rounded-lg border border-stone-200 bg-white p-4"><h2 className="font-serif text-lg">Clientes inativos · 60 dias</h2>{customers.data.filter(c => c.completedVisits > 0 && c.lastVisitAt && Date.now() - new Date(c.lastVisitAt).getTime() > 60 * 24 * 60 * 60 * 1000).length ? <div className="mt-2 divide-y divide-stone-100">{customers.data.filter(c => c.completedVisits > 0 && c.lastVisitAt && Date.now() - new Date(c.lastVisitAt).getTime() > 60 * 24 * 60 * 60 * 1000).map(c => <div key={c.id} className="flex items-center justify-between gap-2 py-2"><span className="text-xs">{c.name} · {new Date(c.lastVisitAt!).toLocaleDateString("pt-BR")}</span><a target="_blank" rel="noreferrer" href={`https://wa.me/${String(c.whatsapp).replace(/\D/g, "")}?text=${encodeURIComponent(`Olá ${c.name}, sentimos sua falta na ${me.data.shop.name}. Quer ver um horário para esta semana?`)}`} className="rounded border border-emerald-200 px-2 py-1 text-[10px] text-emerald-800">Chamar</a></div>)}</div> : <p className="mt-2 text-xs text-stone-500">Nenhum cliente com visita há mais de 60 dias.</p>}</section>
        </div>}
        {!customers.data?.length ? <Empty text={search ? "Nenhum cliente encontrado." : "Ainda não há clientes cadastrados."}/> : <div className="mt-5 divide-y divide-stone-100 rounded-lg border border-stone-200 bg-white">{customers.data.map(c => <div key={c.id} className="p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="font-medium">{c.name}</p><p className="mt-1 text-xs text-stone-500">{c.whatsapp || "Sem WhatsApp cadastrado"} · {c.completedVisits} atendimento(s) concluído(s){c.lastVisitAt ? ` · última visita ${new Date(c.lastVisitAt).toLocaleDateString("pt-BR")}` : ""}</p>{role === "owner" && <p className="mt-1 text-xs text-stone-600">Gasto total registrado: {brl(Number(c.totalSpent ?? 0))} {c.birthday ? `· aniversário ${birthdayMonthDay(c.birthday).slice(3,5)}/${birthdayMonthDay(c.birthday).slice(0,2)}` : ""}{c.notes ? ` · ${c.notes}` : ""}</p>}</div><div className="flex gap-2">{c.whatsapp && <a target="_blank" rel="noreferrer" href={`https://wa.me/${String(c.whatsapp).replace(/\D/g, "")}?text=${encodeURIComponent(`Olá ${c.name}, tudo bem? Aqui é da ${me.data.shop.name}. Como podemos ajudar?`)}`} className="inline-flex items-center gap-2 rounded-md border border-emerald-200 px-3 py-2 text-xs text-emerald-800"><MessageCircle size={15}/>WhatsApp</a>}<button onClick={() => setExpandedHistoryCustomerId(expandedHistoryCustomerId === c.id ? null : c.id)} className="rounded-md border border-stone-200 px-3 py-2 text-xs text-stone-600">{expandedHistoryCustomerId === c.id ? "Fechar histórico" : "Ver histórico"}</button>{isOwner && <button onClick={() => { setEditingCustomerId(editingCustomerId === c.id ? null : c.id); setCustomerDraft({ birthday: birthdayDateInput(c.birthday), notes: c.notes ?? "" }); }} className="rounded-md border border-stone-200 px-3 py-2 text-xs text-stone-600">{editingCustomerId === c.id ? "Fechar edição" : "Editar cadastro"}</button>}</div></div>{expandedHistoryCustomerId === c.id && <div className="mt-4 rounded-md bg-stone-50 p-3"><p className="text-xs font-semibold">Histórico de atendimentos</p>{customerHistory.isLoading ? <p className="mt-2 text-xs text-stone-500">Carregando histórico…</p> : customerHistory.isError ? <p className="mt-2 text-xs text-rose-700">{customerHistory.error.message}</p> : !customerHistory.data?.length ? <p className="mt-2 text-xs text-stone-500">Nenhum atendimento registrado.</p> : <div className="mt-2 divide-y divide-stone-200">{customerHistory.data.map(visit => <div key={visit.id} className="flex flex-wrap justify-between gap-2 py-2 text-xs"><span>{new Date(visit.startsAt).toLocaleDateString("pt-BR")} · {visit.services.join(" · ")} · {visit.barberName ?? "Profissional"} · {statusText[visit.status] ?? visit.status}</span>{visit.total !== null && <strong>{brl(Number(visit.total))}</strong>}</div>)}</div>}</div>}{editingCustomerId === c.id && isOwner && <form onSubmit={e => { e.preventDefault(); updateCustomer.mutate({ id: c.id, birthday: customerDraft.birthday || null, notes: customerDraft.notes.trim() || null }); }} className="mt-4 grid gap-3 rounded-md bg-stone-50 p-3 sm:grid-cols-[180px_1fr_auto]"><label className="text-xs text-stone-500">Aniversário<input type="date" value={customerDraft.birthday} onChange={e => setCustomerDraft({ ...customerDraft, birthday: e.target.value })} className={inputClass}/></label><label className="text-xs text-stone-500">Observações<textarea maxLength={2000} value={customerDraft.notes} onChange={e => setCustomerDraft({ ...customerDraft, notes: e.target.value })} className="mt-1.5 min-h-10 w-full rounded-md border border-stone-200 bg-white p-3 text-sm outline-none focus:border-amber-700"/></label><button disabled={updateCustomer.isPending} className="h-10 self-end rounded-md bg-stone-900 px-4 text-xs text-white">Salvar</button></form>}</div>)}</div>}
      </>}
    </>}
    {section === "servicos" && <><Title eyebrow="Catálogo" title="Serviços" desc="Gerencie opções, preços e duração dos atendimentos."/>{isOwner && <button onClick={()=>{setEditingService(null);setServiceForm({name:"",category:"",iconKey:"scissors",price:"",durationMinutes:"30"});setShowService(!showService)}} className="mt-5 inline-flex items-center gap-2 rounded-md bg-stone-900 px-4 py-2.5 text-sm text-white"><Plus size={16}/>Novo serviço</button>}{showService && isOwner && <form onSubmit={submitService} className="mt-4 grid gap-3 rounded-lg border border-stone-200 bg-white p-4 sm:grid-cols-2 lg:grid-cols-3"><Field label="Nome"><input required minLength={2} maxLength={140} className={inputClass} value={serviceForm.name} onChange={e=>setServiceForm({...serviceForm,name:e.target.value})}/></Field><Field label="Categoria"><input required minLength={2} maxLength={80} className={inputClass} value={serviceForm.category} onChange={e=>setServiceForm({...serviceForm,category:e.target.value})}/></Field><Field label="Ícone"><select className={inputClass} value={serviceForm.iconKey} onChange={e=>setServiceForm({...serviceForm,iconKey:e.target.value})}>{serviceIcons.map(k=><option key={k} value={k}>{({scissors:"Tesoura / corte",beard:"Barba",razor:"Navalha",hair:"Cabelo",eyebrow:"Sobrancelha",pigment:"Pigmentação",hydration:"Hidratação",relaxation:"Relaxamento",star:"Clássico / outros"} as Record<string,string>)[k]}</option>)}</select></Field><Field label="Preço (R$)"><input required type="number" min="0" max="100000" step="0.01" className={inputClass} value={serviceForm.price} onChange={e=>setServiceForm({...serviceForm,price:e.target.value})}/></Field><Field label="Duração (minutos)"><input required type="number" min="5" max="480" className={inputClass} value={serviceForm.durationMinutes} onChange={e=>setServiceForm({...serviceForm,durationMinutes:e.target.value})}/></Field><div className="flex items-end gap-2"><button disabled={createService.isPending||updateService.isPending} className="h-10 rounded-md bg-stone-900 px-4 text-sm text-white">{editingService?"Salvar alterações":"Cadastrar"}</button><button type="button" onClick={()=>{setShowService(false);setEditingService(null)}} className="h-10 px-3 text-sm text-stone-500">Cancelar</button></div></form>}{services.isLoading?<Loading/>:services.isError?<ErrorBox message={services.error.message}/>:!services.data?.length?<Empty text="Nenhum serviço cadastrado."/>:<div className="mt-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{services.data.map(s=><article key={s.id} className="rounded-lg border border-stone-200 bg-white p-4"><div className="flex items-start justify-between"><div><p className="font-medium">{s.name}</p><p className="mt-1 text-xs text-stone-500">{s.category} · {s.durationMinutes} min</p></div><span className={`rounded-full px-2 py-1 text-[10px] ${s.isActive?"bg-emerald-50 text-emerald-700":"bg-stone-100 text-stone-500"}`}>{s.isActive?"Ativo":"Inativo"}</span></div><div className="mt-4 flex items-center justify-between"><span className="font-serif text-xl">{brl(Number(s.price))}</span>{isOwner && <div className="flex gap-2"><button aria-label="Editar serviço" onClick={()=>beginEdit(s)} className="rounded border border-stone-200 p-2 text-stone-600"><Pencil size={15}/></button><button aria-label={s.isActive?"Desativar serviço":"Ativar serviço"} onClick={()=>updateService.mutate({id:s.id,isActive:!s.isActive})} className="rounded border border-stone-200 p-2 text-stone-600">{s.isActive?<ToggleRight size={16}/>:<ToggleLeft size={16}/>}</button></div>}</div></article>)}</div>}</>}
    {section === "equipe" && <><Title eyebrow="Acessos" title="Equipe" desc="Contas e profissionais vinculados a esta barbearia."/>{isOwner && <button onClick={()=>setShowTeam(!showTeam)} className="mt-5 inline-flex items-center gap-2 rounded-md bg-stone-900 px-4 py-2.5 text-sm text-white"><Plus size={16}/>Adicionar integrante</button>}{showTeam && isOwner && <form onSubmit={submitTeam} className="mt-4 grid gap-3 rounded-lg border border-stone-200 bg-white p-4 sm:grid-cols-2"><Field label="Nome"><input required minLength={2} className={inputClass} value={teamForm.name} onChange={e=>setTeamForm({...teamForm,name:e.target.value})}/></Field><Field label="E-mail"><input required type="email" className={inputClass} value={teamForm.email} onChange={e=>setTeamForm({...teamForm,email:e.target.value})}/></Field><Field label="Senha temporária (mínimo 12 caracteres)"><input required minLength={12} type="password" className={inputClass} value={teamForm.password} onChange={e=>setTeamForm({...teamForm,password:e.target.value})}/></Field><Field label="Perfil"><select className={inputClass} value={teamForm.role} onChange={e=>setTeamForm({...teamForm,role:e.target.value as "barber"|"receptionist"})}><option value="barber">Barbeiro</option><option value="receptionist">Recepcionista</option></select></Field>{teamForm.role==="barber" && <div className="sm:col-span-2"><p className="text-xs font-medium">Serviços que realiza</p><div className="mt-2 flex flex-wrap gap-3">{services.data?.filter(s=>s.isActive).map(s=><label key={s.id} className="flex items-center gap-2 text-xs"><input type="checkbox" checked={teamForm.serviceIds.includes(s.id)} onChange={e=>setTeamForm({...teamForm,serviceIds:e.target.checked?[...teamForm.serviceIds,s.id]:teamForm.serviceIds.filter(id=>id!==s.id)})}/>{s.name}</label>)}</div></div>}<div className="sm:col-span-2 flex gap-2"><button disabled={createMember.isPending} className="h-10 rounded-md bg-stone-900 px-4 text-sm text-white">Criar acesso</button><button type="button" onClick={()=>setShowTeam(false)} className="px-3 text-sm text-stone-500">Cancelar</button></div></form>}{team.isLoading?<Loading/>:team.isError?<ErrorBox message={team.error.message}/>:<><h2 className="mb-3 mt-7 text-sm font-semibold">Profissionais</h2>{!team.data?.barbers.length?<Empty text="Nenhum profissional cadastrado."/>:<div className="grid gap-3 sm:grid-cols-2">{team.data.barbers.map(b=><div key={b.id} className="rounded-lg border border-stone-200 bg-white p-4"><p className="font-medium">{b.displayName}</p><p className="mt-1 text-xs text-stone-500">Barbeiro</p></div>)}</div>}{isOwner && !!team.data?.barbers.length && <section className="mt-7 rounded-lg border border-stone-200 bg-white p-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><h2 className="font-serif text-xl">Expediente semanal</h2><p className="mt-1 text-xs text-stone-500">Folgas e intervalos controlam automaticamente os horários de agendamento.</p></div><label className="min-w-[200px] text-xs text-stone-500">Barbeiro<select value={hoursBarberId} onChange={e => setHoursBarberId(e.target.value)} className={inputClass}>{team.data.barbers.map(barber => <option key={barber.id} value={barber.id}>{barber.displayName}</option>)}</select></label></div>{workingHours.isLoading ? <Loading/> : <form onSubmit={e => { e.preventDefault(); saveWorkingHours.mutate({ barberId: Number(hoursBarberId), hours: workingHoursForm }); }} className="mt-4 space-y-2">{workingHoursForm.map((row, index) => <div key={row.weekday} className="grid items-center gap-2 rounded-md bg-stone-50 p-3 sm:grid-cols-[100px_100px_1fr_1fr_1fr_1fr]"><span className="text-xs font-medium">{weekDayLabels[row.weekday]}</span><label className="flex items-center gap-2 text-xs"><input type="checkbox" checked={row.isDayOff} onChange={e => setWorkingHoursForm(old => old.map((item, i) => i === index ? { ...item, isDayOff: e.target.checked } : item))} className="accent-amber-800"/>Folga</label><label className="text-[10px] text-stone-500">Início<input disabled={row.isDayOff} type="time" value={row.startTime} onChange={e => setWorkingHoursForm(old => old.map((item, i) => i === index ? { ...item, startTime: e.target.value } : item))} className={inputClass}/></label><label className="text-[10px] text-stone-500">Fim<input disabled={row.isDayOff} type="time" value={row.endTime} onChange={e => setWorkingHoursForm(old => old.map((item, i) => i === index ? { ...item, endTime: e.target.value } : item))} className={inputClass}/></label><label className="text-[10px] text-stone-500">Início do intervalo<input disabled={row.isDayOff} type="time" value={row.breakStart ?? ""} onChange={e => setWorkingHoursForm(old => old.map((item, i) => i === index ? { ...item, breakStart: e.target.value || null } : item))} className={inputClass}/></label><label className="text-[10px] text-stone-500">Fim do intervalo<input disabled={row.isDayOff} type="time" value={row.breakEnd ?? ""} onChange={e => setWorkingHoursForm(old => old.map((item, i) => i === index ? { ...item, breakEnd: e.target.value || null } : item))} className={inputClass}/></label></div>)}<button disabled={saveWorkingHours.isPending} className="mt-2 rounded-md bg-stone-900 px-4 py-2.5 text-sm text-white">{saveWorkingHours.isPending ? "Salvando…" : "Salvar expediente"}</button></form>}</section>}<h2 className="mb-3 mt-7 text-sm font-semibold">Contas de acesso</h2>{!team.data?.accounts.length?<Empty text="Nenhuma conta de equipe."/>:<div className="divide-y divide-stone-100 rounded-lg border border-stone-200 bg-white">{team.data.accounts.map(a=><div key={a.id} className="flex flex-wrap justify-between gap-2 p-4"><div><p className="font-medium">{a.name}</p><p className="mt-1 text-xs text-stone-500">{a.email}</p></div><span className="self-center rounded-full bg-stone-100 px-2.5 py-1 text-[10px]">{a.role==="barber"?"Barbeiro":a.role==="receptionist"?"Recepcionista":a.role==="owner"?"Dono":a.role}</span></div>)}</div>}</>}</>}
    {section === "configuracoes" && isOwner && <><Title eyebrow="Preferências" title="Configurações" desc="Identidade e recursos disponíveis para sua barbearia."/><form onSubmit={e=>{e.preventDefault();updateSettings.mutate({...settingsForm,name:settingsForm.name.trim(),slug:settingsForm.slug.trim(),logoUrl:settingsForm.logoUrl.trim() || null,bannerImageUrl:settingsForm.bannerImageUrl.trim() || null,cancellationNoticeHours:Number(settingsForm.cancellationNoticeHours)})}} className="mt-6 space-y-5">{settingsForm.bannerImageUrl && <div className="overflow-hidden rounded-lg border border-stone-200 bg-white"><img src={settingsForm.bannerImageUrl} alt="Prévia do banner público" className="h-36 w-full object-cover"/><p className="px-3 py-2 text-[10px] text-stone-500">Prévia do banner público</p></div>}<section className="grid gap-4 rounded-lg border border-stone-200 bg-white p-5 sm:grid-cols-2"><Field label="Nome da barbearia"><input required minLength={2} maxLength={160} className={inputClass} value={settingsForm.name} onChange={e=>setSettingsForm({...settingsForm,name:e.target.value})}/></Field><Field label="URL da logo"><input type="url" maxLength={2048} className={inputClass} value={settingsForm.logoUrl} onChange={e=>setSettingsForm({...settingsForm,logoUrl:e.target.value})} placeholder="https://…"/></Field><Field label="Imagem do banner (URL)"><input type="text" maxLength={2048} className={inputClass} value={settingsForm.bannerImageUrl} onChange={e=>setSettingsForm({...settingsForm,bannerImageUrl:e.target.value})} placeholder="https://… ou /manus-storage/…"/><span className="mt-1 block text-[10px] font-normal text-stone-400">Troque ou remova a imagem quando quiser. Use um link público de imagem.</span></Field><label className="block text-xs font-medium text-stone-600">Ou envie um arquivo<input type="file" accept="image/jpeg,image/png,image/webp" disabled={createBannerUpload.isPending || updateSettings.isPending} onChange={e=>{const file=e.target.files?.[0]; e.target.value=""; if(file) void uploadBannerImage(file);}} className="mt-1.5 block w-full rounded-md border border-stone-200 bg-white px-3 py-2 text-xs file:mr-3 file:rounded file:border-0 file:bg-stone-100 file:px-3 file:py-2"/><span className="mt-1 block text-[10px] font-normal text-stone-400">JPG, PNG ou WebP · até 5 MB</span></label><Field label="Link / slug"><input required minLength={2} maxLength={80} pattern="[a-z0-9][a-z0-9-]*[a-z0-9]|[a-z0-9]{2}" className={inputClass} value={settingsForm.slug} onChange={e=>setSettingsForm({...settingsForm,slug:e.target.value.toLowerCase().replace(/[^a-z0-9-]/g,"")})}/><span className="mt-1 block text-[10px] text-stone-400">Minúsculas, números e hífens, sem espaços.</span></Field><Field label="Cor principal"><div className="mt-1.5 flex h-10 items-center gap-2"><input type="color" value={settingsForm.primaryColor} onChange={e=>setSettingsForm({...settingsForm,primaryColor:e.target.value})} className="h-10 w-12 rounded border border-stone-200 p-1"/><input value={settingsForm.primaryColor} maxLength={7} onChange={e=>setSettingsForm({...settingsForm,primaryColor:e.target.value})} className="h-10 w-28 rounded border border-stone-200 px-3 text-sm"/></div></Field><Field label="Antecedência mínima para cancelamento (horas)"><input type="number" min="0" max="168" className={inputClass} value={settingsForm.cancellationNoticeHours} onChange={e=>setSettingsForm({...settingsForm,cancellationNoticeHours:Number(e.target.value)})}/></Field></section><section className="rounded-lg border border-stone-200 bg-white p-5"><h2 className="font-medium">Recursos do espaço público</h2><p className="mt-1 text-xs text-stone-500">Ative ou oculte recursos exibidos na página da barbearia.</p><div className="mt-3 divide-y divide-stone-100">{([["plansVisible","Planos"],["promotionsEnabled","Promoções"],["couponsEnabled","Cupons"],["loyaltyEnabled","Fidelidade"],["reviewsEnabled","Avaliações"],["galleryEnabled","Galeria"]] as const).map(([k,label])=><label key={k} className="flex cursor-pointer items-center justify-between py-3 text-sm"><span>{label}</span><input type="checkbox" checked={settingsForm[k]} onChange={e=>setSettingsForm({...settingsForm,[k]:e.target.checked})} className="h-4 w-4 accent-amber-800"/></label>)}</div></section>{settingsForm.reviewsEnabled && <section className="rounded-lg border border-stone-200 bg-white p-5"><h2 className="font-medium">Avaliações por barbeiro</h2><p className="mt-1 text-xs text-stone-500">A média considera apenas as avaliações visíveis ao público.</p>{reviewStats.isLoading ? <Loading/> : reviewStats.isError ? <ErrorBox message={reviewStats.error.message}/> : <div className="mt-3 divide-y divide-stone-100">{(reviewStats.data ?? []).map(item => <div key={item.barberId} className="flex items-center justify-between py-2 text-sm"><span>{item.barberName}</span><span className="text-xs text-stone-500">{item.average ? `${item.average}/5` : "Sem avaliações"} · {item.count} avaliação(ões)</span></div>)}</div>}</section>}<button disabled={updateSettings.isPending} className="inline-flex items-center gap-2 rounded-md bg-stone-900 px-5 py-2.5 text-sm text-white"><Save size={15}/>{updateSettings.isPending?"Salvando…":"Salvar configurações"}</button></form></>}

  </div></main>{payingId !== null && <div className="fixed inset-0 z-50 grid place-items-center bg-black/40 p-4"><div className="w-full max-w-sm rounded-xl bg-white p-5 shadow-xl"><h2 className="font-serif text-2xl">Concluir atendimento</h2><p className="mt-1 text-sm text-stone-500">Selecione a forma de pagamento para registrar a conclusão.</p><label className="mt-4 block text-xs font-medium">Forma de pagamento<select className={inputClass} value={paymentMethod} onChange={e=>setPaymentMethod(e.target.value as typeof paymentMethod)}><option value="cash">Dinheiro</option><option value="pix">Pix</option><option value="credit">Crédito</option><option value="debit">Débito</option><option value="other">Outro</option></select></label><label className="mt-3 block text-xs font-medium">Taxa da maquininha (R$)<input type="number" min="0" step="0.01" value={machineFee} onChange={e=>setMachineFee(e.target.value)} className={inputClass}/></label><div className="mt-4 rounded-lg border border-stone-200 p-3"><p className="text-xs font-semibold">Serviços realizados</p>{appointmentServices.isLoading ? <p className="mt-2 text-xs text-stone-500">Carregando serviços do agendamento…</p> : appointmentServices.isError ? <p className="mt-2 text-xs text-rose-700">{appointmentServices.error.message}</p> : <div className="mt-2 grid gap-2 sm:grid-cols-2">{(services.data ?? []).filter(service => service.isActive || appointmentServices.data?.some(item => item.serviceId === service.id)).map(service => <label key={service.id} className="flex items-center justify-between gap-2 rounded border border-stone-100 p-2 text-xs"><span>{service.name} · {brl(Number(service.price))} · {service.durationMinutes} min</span><input type="checkbox" checked={selectedServiceIds.includes(service.id)} onChange={e => setSelectedServiceIds(old => e.target.checked ? [...old, service.id] : old.filter(id => id !== service.id))} className="accent-amber-800"/></label>)}</div>}{selectedServiceIds.length === 0 && <p className="mt-2 text-xs text-rose-700">Selecione pelo menos um serviço realizado.</p>}</div><div className="mt-4 rounded-lg border border-stone-200 p-3"><p className="text-xs font-semibold">Produtos neste atendimento</p><div className="mt-2 flex flex-wrap gap-2"><select aria-label="Produto" value={productDraftId} onChange={e=>setProductDraftId(e.target.value)} className="h-9 min-w-0 flex-1 rounded-md border border-stone-200 bg-white px-2 text-xs"><option value="">Adicionar produto…</option>{(saleProducts.data ?? []).map(p=><option key={p.id} value={p.id} disabled={p.quantity<1}>{p.name} · {brl(Number(p.salePrice))} · estoque {p.quantity}</option>)}</select><input aria-label="Quantidade" className="h-9 w-16 rounded-md border border-stone-200 px-2 text-xs" type="number" min="1" value={productDraftQuantity} onChange={e=>setProductDraftQuantity(e.target.value)}/><button type="button" disabled={!productDraftId} onClick={()=>{const productId=Number(productDraftId), quantity=Number(productDraftQuantity);setProductSelection(old=>{const found=old.find(x=>x.productId===productId);return found?old.map(x=>x.productId===productId?{...x,quantity:x.quantity+quantity}:x):[...old,{productId,quantity}];});setProductDraftId("");setProductDraftQuantity("1");}} className="rounded-md border border-stone-200 px-3 text-xs">Adicionar</button></div>{productSelection.length>0&&<div className="mt-2 space-y-1">{productSelection.map(line=>{const product=saleProducts.data?.find(p=>p.id===line.productId);return <div key={line.productId} className="flex justify-between text-xs text-stone-600"><span>{product?.name??"Produto"} × {line.quantity}</span><button type="button" onClick={()=>setProductSelection(old=>old.filter(x=>x.productId!==line.productId))} className="text-rose-700">Remover</button></div>;})}</div>}</div><div className="mt-5 flex justify-end gap-2"><button onClick={()=>setPayingId(null)} className="rounded-md px-3 py-2 text-sm text-stone-500">Cancelar</button><button disabled={statusUpdate.isPending || appointmentServices.isLoading || appointmentServices.isError || selectedServiceIds.length === 0} onClick={completeWithPayment} className="rounded-md bg-stone-900 px-4 py-2 text-sm text-white">{statusUpdate.isPending?"Salvando…":"Concluir"}</button></div></div></div>}</div>;
}
function Loading(){return <div className="mt-10 flex items-center justify-center gap-2 text-sm text-stone-500"><LoaderCircle size={17} className="animate-spin"/>Carregando dados…</div>}
function ErrorBox({message}:{message:string}){return <div role="alert" className="mt-6 rounded-lg border border-rose-200 bg-rose-50 p-4 text-sm text-rose-800">Não foi possível carregar os dados: {message}</div>}
function Empty({text}:{text:string}){return <div className="mt-5 rounded-lg border border-dashed border-stone-300 bg-white/60 p-10 text-center text-sm text-stone-500">{text}</div>}
function Title({eyebrow,title,desc}:{eyebrow:string,title:string,desc:string}){return <div><p className="text-[10px] font-semibold uppercase tracking-[.2em] text-amber-800">{eyebrow}</p><h1 className="mt-1 font-serif text-3xl">{title}</h1><p className="mt-1 text-sm text-stone-500">{desc}</p></div>}
function Field({label,children}:{label:string,children:React.ReactNode}){return <label className="block text-xs font-medium text-stone-600">{label}{children}</label>}
